#!/usr/bin/env bash
#
# A wizard walks a human through setting up Firebase Spark for Smart Gameya.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

TOTAL_STAGES=6

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  هذا المعالج التفاعلي يرشدك خطوة بخطوة لإعداد مشروع Firebase المجاني (Spark Tier)\n' "$DIM"
  printf '  وتهيئة Authentication و Firestore و Storage، وحفظ ملفات الربط تلقائياً.%s\n\n' "$RESET"
  pause "اضغط Enter للبدء..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ المرحلة %s/%s · %s%s\n\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ جاري فتح المتصفح:%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview      >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open     >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open         >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "تعذر فتح المتصفح تلقائياً، يرجى فتح الرابط يدوياً: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-اضغط Enter للمتابعة}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

ask() {
  local key="$1" prompt="$2" input=""
  printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  read -e -r input || true
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ تم الحفظ%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

finish() {
  _clear
  printf '\n%s%s  ✓ اكتملت تهيئة Firebase بنجاح!%s\n\n' "$BOLD" "$GREEN" "$RESET"
  note "تم حفظ إعدادات المشروع في $ENV_FILE"
  note "الملفات المهيأة:"
  [[ -f "mobile/android/app/google-services.json" ]] && note "  - mobile/android/app/google-services.json (Android)"
  [[ -f "mobile/ios/Runner/GoogleService-Info.plist" ]] && note "  - mobile/ios/Runner/GoogleService-Info.plist (iOS)"
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

banner "إعداد وربط مشروع Firebase (Smart Gameya)"

# ── المرحلة 1: إنشاء المشروع ──────────────────────────────────────────────
stage "إنشاء مشروع Firebase جديد"
say "سنقوم بإنشاء مشروع مجاني على منصة Firebase Console."
open_url "https://console.firebase.google.com/"
step "1. اضغط على 'Add project' (إضافة مشروع)."
step "2. أدخل اسم المشروع (مثلاً: smart-gameya-prod)."
step "3. عطل Google Analytics أو فعله حسب رغبتك (اختياري)."
step "4. اضغط 'Create project' وانتظر اكتمال الإنشاء."
say ""
ask FIREBASE_PROJECT_ID "أدخل معرف المشروع (Project ID) الذي تم إنشاؤه:"
write_env FIREBASE_PROJECT_ID "$FIREBASE_PROJECT_ID"
pause "اضغط Enter للانتقال للمرحلة التالية..."

# ── المرحلة 2: تفعيل Authentication ───────────────────────────────────────
stage "تفعيل تسجيل الدخول بـ Google (Authentication)"
say "سنفعل مزود تسجيل الدخول بواسطة Google."
open_url "https://console.firebase.google.com/project/${FIREBASE_PROJECT_ID}/authentication"
step "1. اضغط على زر 'Get started' (البدء)."
step "2. في تبويب 'Sign-in method'، اختر 'Google'."
step "3. فعّل خيار 'Enable'."
step "4. اختر بريد الدعم (Support email) واضغط 'Save'."
say ""
pause "اضغط Enter بعد تفعيل Google Sign-In..."

# ── المرحلة 3: تفعيل Cloud Firestore ─────────────────────────────────────
stage "إنشاء وتفعيل قاعدة بيانات Cloud Firestore"
say "سننشئ قاعدة بيانات Firestore لتخزين الجمعيات والأقساط."
open_url "https://console.firebase.google.com/project/${FIREBASE_PROJECT_ID}/firestore"
step "1. اضغط على 'Create database'."
step "2. اختر أقرب موقع خادم (مثلاً eur3 في غرب أوروبا أو me-central1)."
step "3. اختر 'Start in production mode' (وضع الإنتاج)."
step "4. اضغط 'Create'."
say ""
pause "اضغط Enter بعد اكتمال إنشاء قاعدة البيانات..."

# ── المرحلة 4: تفعيل Cloud Storage ───────────────────────────────────────
stage "تفعيل Cloud Storage لإيصالات التحويل"
say "سنفعل مساحة التخزين السحابية لصور إيصالات فودافون كاش وإنستاباي."
open_url "https://console.firebase.google.com/project/${FIREBASE_PROJECT_ID}/storage"
step "1. اضغط على 'Get started'."
step "2. اختر 'Start in production mode'."
step "3. اعتمد الموقع الافتراضي واضغط 'Done'."
say ""
pause "اضغط Enter بعد اكتمال تفعيل Cloud Storage..."

# ── المرحلة 5: إضافة تطبيق Android وملف google-services.json ────────────
stage "إضافة تطبيق Android وتحميل google-services.json"
say "سنربط تطبيق الأندرويد بمشروع Firebase."
open_url "https://console.firebase.google.com/project/${FIREBASE_PROJECT_ID}/settings/general"
step "1. انزل إلى قسم 'Your apps' واضغط على أيقونة Android."
step "2. أدخل معرف الحزمة (Package Name): com.gameya.platform"
step "3. الاسم المستعار (Nickname): Smart Gameya Android"
step "4. اضغط 'Register app'."
step "5. حمّل ملف google-services.json."
say ""
mkdir -p mobile/android/app
ask ANDROID_JSON_PATH "أدخل المسار الكامل لملف google-services.json المُحمّل (أو اسحبه للترمينال):"
if [[ -f "$ANDROID_JSON_PATH" ]]; then
  cp "$ANDROID_JSON_PATH" mobile/android/app/google-services.json
  printf '  %s✓ تم نسخ الملف بنجاح إلى: mobile/android/app/google-services.json%s\n' "$GREEN" "$RESET"
else
  warn "لم يتم العثور على الملف في المسار المدخل. يمكنك وضعه يدوياً في: mobile/android/app/google-services.json"
fi
pause "اضغط Enter للمتابعة..."

# ── المرحلة 6: إضافة تطبيق iOS وملف GoogleService-Info.plist ─────────────
stage "إضافة تطبيق iOS وتحميل GoogleService-Info.plist"
say "سنربط تطبيق الـ iOS بمشروع Firebase."
open_url "https://console.firebase.google.com/project/${FIREBASE_PROJECT_ID}/settings/general"
step "1. في قسم 'Your apps'، اضغط 'Add app' واختر أيقونة Apple (iOS)."
step "2. أدخل معرف الحزمة (Bundle ID): com.gameya.platform"
step "3. الاسم المستعار: Smart Gameya iOS"
step "4. اضغط 'Register app'."
step "5. حمّل ملف GoogleService-Info.plist."
say ""
mkdir -p mobile/ios/Runner
ask IOS_PLIST_PATH "أدخل المسار الكامل لملف GoogleService-Info.plist المُحمّل (أو اتركه فارغاً إذا كنت لا تستهدف iOS الآن):"
if [[ -n "$IOS_PLIST_PATH" && -f "$IOS_PLIST_PATH" ]]; then
  cp "$IOS_PLIST_PATH" mobile/ios/Runner/GoogleService-Info.plist
  printf '  %s✓ تم نسخ الملف بنجاح إلى: mobile/ios/Runner/GoogleService-Info.plist%s\n' "$GREEN" "$RESET"
else
  note "تم تخطي نسخ ملف iOS (يمكن إضافته لاحقاً في mobile/ios/Runner/GoogleService-Info.plist)"
fi

finish
}

run_wizard "$@"; exit
